import{_ as r,o as a,c as i,aw as l}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"React Fiber Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/framework-react/react/fiber/common.md","filePath":"wiki/dev-commit/framework-react/react/fiber/common.md"}'),t={name:"wiki/dev-commit/framework-react/react/fiber/common.md"};function o(c,e,n,s,u,d){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="react-fiber-architecture" tabindex="-1">React Fiber Architecture <a class="header-anchor" href="#react-fiber-architecture" aria-label="Permalink to &quot;React Fiber Architecture&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="https://www.youtube.com/watch?v=4p9ISqIx1zI" target="_blank" rel="noreferrer">https://www.youtube.com/watch?v=4p9ISqIx1zI</a></p></div><ul><li><strong>React Fiber</strong> - переделанная реализация алгоритма reconciliation</li><li>Fiber - легоковесная реализация потоков</li><li>Цель Fiber - позволить React воспользоваться планированием</li><li><strong>Планирование</strong> - это процесс, который определяет когда работа должна быть выполнена</li><li><strong>Работа</strong> - любые вычисления, которые должны быть выполнены. Работа – это обычно результат апдейта (например вызов setState)</li><li>Цель в увеличении производительности при разработке таких задач как анимация, организация элементов на странице и движение элементов</li><li>Главная особенность - инкрементный рендеринг: способность разделять работу рендера на единицы и распределять их между множественными фреймами.</li></ul><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><ul><li><ol><li>Есть очередь того, что нужно перерисовать</li></ol></li><li><ol start="2"><li>У каждого элемента очереди есть приоритеты</li></ol></li><li><ol start="3"><li>Механизм реконсилинга выбирает из очереди наиболее приоритетные задачи, их выполняет пока не прошло 16ms и не пришло время отдавать управление браузеру</li></ol></li></ul><h2 id="фазы" tabindex="-1">Фазы <a class="header-anchor" href="#фазы" aria-label="Permalink to &quot;Фазы&quot;">​</a></h2><ul><li>Фазу 1 можно прервать</li><li>Фазу 2 нельзя прервать</li></ul><h2 id="сравнение-с-предыдущим-алгоритмом" tabindex="-1">Сравнение с предыдущим алгоритмом <a class="header-anchor" href="#сравнение-с-предыдущим-алгоритмом" aria-label="Permalink to &quot;Сравнение с предыдущим алгоритмом&quot;">​</a></h2><ul><li>Предудущий алгоритм обходит всё дерево компонент рекурсивно и вызывает все render-функции в рамках одного тика Event Loop.</li></ul><h2 id="error-boundarys" tabindex="-1">Error Boundarys <a class="header-anchor" href="#error-boundarys" aria-label="Permalink to &quot;Error Boundarys&quot;">​</a></h2><ul><li>Каждая отрисовка является легковесным Файбером стало возможно реализовать границы ошибок (Error Boundarys)</li><li>Теперь падения в одном компоненте не приводит к падению перерисовок во всех других компонентов</li><li>Будет разрушено дерево компонента, который упал. Но за пределы разрушенного дерева, ошибка не выйдет</li></ul><h2 id="из-компонентов-react-можно-возвращать" tabindex="-1">Из компонентов React можно возвращать: <a class="header-anchor" href="#из-компонентов-react-можно-возвращать" aria-label="Permalink to &quot;Из компонентов React можно возвращать:&quot;">​</a></h2><ul><li>DOM-узел</li><li>Число</li><li>Строку</li><li>Массив (DOM-узелов / чисел / строк)</li></ul><p>Нет соответствия: 1 виртуальный узел - 1 узел в HTML</p><h2 id="повторныи-рендеринг-re-renderen" tabindex="-1">Повторный рендеринг (Re-renderen) <a class="header-anchor" href="#повторныи-рендеринг-re-renderen" aria-label="Permalink to &quot;Повторный рендеринг (Re-renderen)&quot;">​</a></h2><ul><li><ol><li>Сверка (Reconciler)</li></ol></li><li><ol start="2"><li>Перерисовка (Rerender): ReactDOM, React Native</li></ol></li></ul>',16)])])}const b=r(t,[["render",o]]);export{m as __pageData,b as default};
